"""Generate DATA_AVAILABILITY.md from the provenance logs and the SHA256 of every archived raw file.
Run: python -m src.mk_data_availability   (called by run_all.sh before numbers_v7)
"""
from __future__ import annotations
import datetime as dt, json
from pathlib import Path
import requests
from src.genes import *   # noqa
from src.mg_clinvar import sha256


def row(*c):
    return "| " + " | ".join(str(x) for x in c) + " |"


def main():
    pv = json.loads((LOGS / "provenance_acquire_v7.json").read_text())
    pc = json.loads((LOGS / "provenance_clinvar_v7.json").read_text())
    p6 = json.loads((LOGS / "provenance_acquisition.json").read_text())
    try:
        up = requests.head("https://rest.uniprot.org/uniprotkb/search?query=gene_exact:TP53&size=1", timeout=30).headers
        uprel = f"{up.get('x-uniprot-release')} ({up.get('x-uniprot-release-date')})"
    except Exception:  # noqa
        uprel = "release header not retrievable at generation time"
    try:
        mv = requests.get("https://myvariant.info/v1/metadata", timeout=30).json()
        mvb = f"build {mv.get('build_date')}; sources: ClinVar {mv['src']['clinvar'].get('version')}, dbNSFP {mv['src']['dbnsfp'].get('version')}"
    except Exception:  # noqa
        mvb = "build metadata not retrievable at generation time"
    L = ["# DATA_AVAILABILITY (generated by src/mk_data_availability.py; checksums are SHA256 of the archived files in this package)", "",
         f"Generated: {dt.datetime.utcnow().isoformat()}Z. All sources below are public and were accessed without login.", "",
         "## Public sources", "",
         row("Source", "URL / endpoint", "Release / version / date", "Local archived file", "SHA256"),
         row("---", "---", "---", "---", "---"),
         row("ClinVar variant_summary (germline classifications, review status, GRCh37/38 coordinates)",
             "https://ftp.ncbi.nlm.nih.gov/pub/clinvar/tab_delimited/variant_summary.txt.gz",
             f"server Last-Modified {pc.get('server_last_modified_now')}; file mtime {pc.get('file_mtime_utc')}; {pc.get('bytes')} bytes",
             "data/raw/variant_summary.txt.gz", pc.get("sha256")),
         row("NCBI E-utilities (independent ClinVar MYH7 count, v6 step)", "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi", f"queried {p6.get('run_started_utc')}", "logs/provenance_acquisition.json", "n/a (counts only)"),
         row("ClinGen Evidence Repository (all classifications, TSV)", "https://erepo.clinicalgenome.org/evrepo/api/classifications/all", "accessed 2026-10-07 (no login; filter parameters ignored, full table)",
             "data/raw/erepo_classifications_all.tsv", sha256(RAW / "erepo_classifications_all.tsv")),
         row("gnomAD v4 (dataset gnomad_r4, GRCh38) per-gene variants", "https://gnomad.broadinstitute.org/api (GraphQL)", "dataset id gnomad_r4 = release 4.1.0 per gnomAD's dataset documentation; the GraphQL API does not echo the patch version, so this was not confirmed from the responses",
             "data/raw/gnomad/<GENE>_gnomad_r4.parquet", "see table below"),
         row("MyVariant.info (dbNSFP predictors incl. AlphaMissense, REVEL, CADD; ClinVar snapshot used only for the retrieval audit)", "https://myvariant.info/v1/variant (POST) and /v1/query (scroll)", mvb,
             "data/raw/myvariant/*.parquet, data/raw/audit/*.parquet", "see manifest below"),
         row("AlphaFold DB models (AF-<UniProt>-F1)", "https://alphafold.ebi.ac.uk/api/prediction/<UniProt>", "model version " + ", ".join(sorted({str(v.get('model_version')) for v in pv.values() if v.get('available')})),
             "data/external/alphafold/*.pdb; data/external/AF-P12883-F1-model_v6.pdb", "see table below"),
         row("UniProt (accession lookup for the extra genes)", "https://rest.uniprot.org/uniprotkb/search", uprel, "data/interim/extra_genes.csv", sha256(INTERIM / "extra_genes.csv") if (INTERIM / "extra_genes.csv").exists() else "n/a"),
         row("Kelly et al. 2018 (BS1/BA1 for MYH7), verified from open-access full text", "https://doi.org/10.1038/gim.2017.218 (EuropePMC PMC5876064)", "Genet Med 20:351-359; BA1 filtering AF 0.1%, BS1 0.02%, PM2 0.004%", "(text only; thresholds quoted in PREREG.md)", "n/a"),
         row("Friedman et al. 2024 supplements (preprint v1) for the MYH7 overlap check", "https://www.biorxiv.org/content/10.1101/2023.07.28.551073v1.supplementary-material", "preprint v1 (see data/external/friedman2024/SOURCES.md)",
             "data/external/friedman2024/*", sha256(Path("data/external/friedman2024/friedman2024_scores.csv"))),
         row("Frozen truncated v5 analysis table (project-internal; used only by the legacy comparison and validation steps, Supplement S1 and one paired contrast (last row of Table S7, counted in Table 3))", "(internal to the author's earlier analysis; not public)", "frozen in v7; see data/legacy_v5/SHA256SUMS", "data/legacy_v5/*.parquet",
             "; ".join(f"{Path(f).name}: {sha256(Path(f))[:16]}..." for f in sorted(Path('data/legacy_v5').glob('*.parquet')))), "",
         "## Per-gene archived files (SHA256)", "", row("Gene", "UniProt", "AF model version", "AF pdb sha256", "gnomAD parquet sha256", "gnomAD missense variants"), row("---", "---", "---", "---", "---", "---")]
    for g, info in pv.items():
        gp = RAW / "gnomad" / f"{g}_gnomad_r4.parquet"
        L.append(row(g, UNIPROT.get(g, ""), info.get("model_version"), (info.get("pdb_sha256") or "no model")[:20] + ("..." if info.get("pdb_sha256") else ""),
                     (sha256(gp)[:20] + "...") if gp.exists() else "n/a", info.get("gnomad_n_missense")))
    L += ["", "## What 'from scratch' means for run_all.sh", "",
          "* Re-run from archived downloads: every derived table, feature file, score, inference result, figure, the reference list, the paper PDFs and the response letter are deleted and rebuilt. Inputs are the archived files listed above (SHA256 in this file), the archived v6 acquisition table data/processed/myh7_all_variants_annotated.parquet (the output of the live MyVariant.info and gnomAD queries of the earlier analysis, kept so that those live services are not queried again) and the frozen legacy v5 table (data/legacy_v5/SHA256SUMS).",
          "* Downloaded only on the first ever run, never on a re-run: ClinVar variant_summary.txt.gz, gnomAD GraphQL per-gene tables, MyVariant.info annotations and audit queries, AlphaFold DB models, UniProt accessions, the ClinGen Evidence Repository table, the Friedman et al. preprint supplement. FORCE_DOWNLOAD=1 repeats these downloads. A forced run was NOT performed for the paper: live services are updated, so a fresh download is not expected to be byte-identical (ClinVar is a new monthly release, MyVariant.info and gnomAD may change).",
          "* Erratum: PREREG.md (hashed, therefore not edited) says the ClinGen Evidence Repository table has 6,342 rows; the archived file has 6,343 data rows. The MYH7 count (171) is unchanged.",
          "* Live metadata requests on every run, even from cache: mg_acquire asks the AlphaFold DB prediction API for each gene's entry (the model file itself is read from the archive), and this file's generation asks UniProt and MyVariant.info for their release headers. These requests do not replace archived data, but they need network access and would show a changed AlphaFold DB version if the service changed.",
          "* Crossref metadata for the references are cached in paper/references_crossref.json; the reference step queries Crossref only for DOIs missing from the cache.",
          "* Tools: Python and packages as in requirements.lock.txt (interpreter chosen by run_all.sh: $PYTHON, ./.venv, ../.venv, then python3) and the tectonic LaTeX engine ($TECTONIC or PATH).", "", "## Notes", "",
          "* Live services (MyVariant.info, gnomAD API, AlphaFold DB, UniProt, ClinGen) change over time; run_all.sh reuses the archived files and only refetches when FORCE_DOWNLOAD=1. The ClinVar release is pinned by its SHA256.",
          "* MyVariant.info serves a ClinVar snapshot dated 2025-05 and dbNSFP 4.8a, older than the ClinVar variant_summary used for labels; this is why the retrieval audit exists. Predictor scores are taken from dbNSFP 4.8a only.",
          "* The legacy truncated v5 table is not public; it is frozen here only so the legacy comparison can be re-run. Apart from that one paired contrast of Table S7 (counted in Table 3), nothing in the multi-gene or tier analyses depends on it.",
          "* Licences: ClinVar and ClinGen data are public (NCBI/ClinGen terms); gnomAD data are open under the gnomAD terms of use; AlphaFold DB models are CC-BY 4.0; dbNSFP/MyVariant carry the licences shown in each response (`_license` fields); check each before redistribution."]
    Path("DATA_AVAILABILITY.md").write_text("\n".join(L) + "\n")
    print("written DATA_AVAILABILITY.md")


if __name__ == "__main__":
    main()
